// T: 指定 lang の key を引く.  未登録時は ja に fallback, ja にも無ければ key 自身を返す.
func T(lang Lang, key string) string {
	v := key
	if d, ok := dict[lang]; ok {
		if s, ok := d[key]; ok {
			v = s
		} else if s, ok := dict[LangJA][key]; ok {
			v = s
		}
	} else if s, ok := dict[LangJA][key]; ok {
		v = s
	}
	// Append the concrete restart command as a parenthetical ONLY when the init
	// system is known; otherwise the placeholder vanishes and the sentence keeps
	// its plain-words "restart unmask".  No-op for keys without the placeholder.
	hint := ""
	if RestartCmd != "" {
		hint = " (<code>sudo " + RestartCmd + "</code>)"
	}
	return strings.ReplaceAll(v, restartHintPlaceholder, hint)
}

// Tf: T + fmt.Sprintf.  placeholder 入りの message に使う.
func Tf(lang Lang, key string, args ...any) string {
	return fmt.Sprintf(T(lang, key), args...)
}

// HelpJSON: dashboard の <script id="help-data"> に inline する JSON を返す.
//
// dict 内 "help.<key>" 形式の entry を、 "<key>" を field 名にした map にして
// JSON.Marshal する.  ja に missing で en だけにある key は en も拾うため両方 union.
// 値は dashboard.html の <span data-help-key="<key>"> と一致する key にしている.
func HelpJSON(lang Lang) string {
	out := make(map[string]string, 64)
	collect := func(d map[string]string) {
		for k, v := range d {
			if !strings.HasPrefix(k, "help.") {
				continue
			}
			short := k[len("help."):]
			out[short] = v
		}
	}
	// ja を base にして lang で上書き (= 未訳 key は ja fallback).
	collect(dict[LangJA])
	if lang != LangJA {
		if d, ok := dict[lang]; ok {
			for k, v := range d {
				if !strings.HasPrefix(k, "help.") {
					continue
				}
				out[k[len("help."):]] = v
			}
		}
	}
	body, err := json.Marshal(out)
	if err != nil {
		return "{}"
	}
	return string(body)
}

// Resolve: HTTP request から lang を決める.  優先度:
//
//  1. cookie unmask_locale (= picker UI が書く)
//  2. Accept-Language header (= 最初に match した supported lang)
//  3. default = ja
func Resolve(r *http.Request) Lang {
	if r != nil {
		if c, err := r.Cookie(CookieName); err == nil && c != nil {
			if isSupported(Lang(c.Value)) {
				return Lang(c.Value)
			}
		}
		if al := r.Header.Get("Accept-Language"); al != "" {
			// 単純 parse: "en-US,en;q=0.9,ja;q=0.8" → 順に取り出して supported だったら採用.
			for _, part := range strings.Split(al, ",") {
				code := strings.TrimSpace(part)
				if i := strings.IndexByte(code, ';'); i >= 0 {
					code = code[:i]
				}
				// "en-US" → "en"
				if i := strings.IndexByte(code, '-'); i >= 0 {
					code = code[:i]
				}
				if isSupported(Lang(code)) {
					return Lang(code)
				}
			}
		}
	}
	return LangJA
}

func isSupported(l Lang) bool {
	for _, s := range SupportedLangs {
		if s == l {
			return true
		}
	}
	return false
}
